-- ============================================================================
--  CP5 — Seed: histórico sintético das últimas 2h (MOTOR_01 e MOTOR_02)
--  Estável: temperatura ~62°C (MOTOR_01) / ~45°C (MOTOR_02) com ruído leve,
--  demais grandezas nominais. 24 amostras por máquina, a cada 5 min, com
--  timestamps relativos a NOW() (sempre "últimas 2h" a partir da aplicação
--  deste script). origem='validacao' (ver contracts/leitura.schema.json).
--
--  Idempotente: apaga a própria janela antes de inserir, então reaplicar
--  produz o mesmo estado (sem duplicar linhas).
--  Usado como baseline por db/cenarios/reset_estavel.sql.
-- ============================================================================
USE fabrica_iot;

DELETE FROM leituras
WHERE id_maquina IN ('MOTOR_01', 'MOTOR_02')
  AND origem = 'validacao'
  AND ts >= NOW() - INTERVAL 130 MINUTE;

